sys_script_include.script:
var GenerateRiskAssessmentPDF = Class.create();
GenerateRiskAssessmentPDF.prototype = {

    initialize: function() {},
    showButton: function(entityId) {
        if (!entityId) {
            gs.error('Entity ID is required.');
            return false;
        }

        // Query risk assessments related to the entity
        var gr = new GlideRecord('sn_risk_advanced_risk_assessment_instance');
        gr.addQuery('entity_1', entityId);
        gr.addEncodedQuery('stateIN7,8'); // State 7 and 8
        gr.query();

        // Return true if at least one record matches
        return gr.hasNext();
    },

    generatePDF: function(entityId) {
        if (!entityId) {
            gs.error('Entity ID is required.');
            return null;
        }

        // Data Access Layer for fetching required data
        var DataAccess = {
            getEntity: function(entityId) {
                var gr = new GlideRecord('sn_grc_profile');
                gr.addQuery('sys_id', entityId);
                gr.query();
                return gr.next() ? gr : null;
            },
            getRiskAssessment: function(entityId) {
                var gr = new GlideRecord('sn_risk_advanced_risk_assessment_instance');
                gr.addQuery('entity_1', entityId);
                gr.addEncodedQuery('stateIN7,8');
                gr.query();
                return gr;
            },
            getControlResponses: function(assessmentId) {
                var controls = [];
                var gr = new GlideRecord('sn_risk_advanced_risk_assessment_instance_response');
                gr.addEncodedQuery('assessment_instance_id.sys_id=' + assessmentId + '^assessment_type=2'); // 2 represents control responses
                gr.query();
                while (gr.next()) {
                    controls.push({
                        name: gr.getDisplayValue('control'),
                        score: gr.getValue('factor_response'),
                        comments: gr.getValue('additional_comments')
                    });
                }
                return controls;
            },
            getAggregatedRisk: function(entityId) {
                var gr = new GlideRecord('sn_risk_advanced_risk_assessment_result');
                gr.addQuery('entity', entityId);
                gr.query();
                if (gr.next()) {
                    return {
                        inherent_rating_display: gr.getValue('inherent_rating_display'),
                        residual_rating_display: gr.getValue('residual_rating_display')
                    };
                }
                return {
                    inherent_rating_display: 'N/A',
                    residual_rating_display: 'N/A'
                };
            },
            getIssues: function(entityId) {
                var issues = [];
                var gr = new GlideRecord('sn_grc_issue');
                gr.addQuery('profile', entityId);
                gr.query();
                while (gr.next()) {
                    issues.push({
                        sys_id: gr.getValue('sys_id'),
                        name: gr.getValue('short_description')
                    });
                }
                return issues;
            },
            getRemediationTasks: function(issueId) {
                var tasks = [];
                var gr = new GlideRecord('sn_grc_task');
                gr.addQuery('issue', issueId);
                gr.query();
                while (gr.next()) {
                    var gdt_end_date = new GlideDateTime(gr.end_date);
                    var datePart = gdt_end_date.getLocalDate().toString();

                    tasks.push({
                        short_description: gr.getValue('short_description'),
                        description: gr.getValue('description'),
                        planned_end_date: datePart
                        //planned_end_date: gr.getDisplayValue('end_date')
                    });
                }
                return tasks;
            },
            getAssessor: function(entityId) {
                var gr = new GlideRecord('sn_risk_advanced_risk_assessment_scope');
                gr.addQuery('entity', entityId);
                gr.addQuery('risk_assessment_methodology', '2a52177f4714d2d097744049116d43ee');
                gr.query();
                if (gr.next()) {
                    return gr.getDisplayValue('assessor') || "(Assessor not found)";
                }
                return "(Assessor not found)";
            },
            getEntityInformation: function(entity) {
                var gr = new GlideRecord('cmdb_ci_service');
                gr.addQuery('sys_id', entity.applies_to);
                gr.query();

                if (gr.next()) {
                    var personal_info = 'N/A';
                    if (gr.u_personal_information == 'yes') {
                        personal_info = gs.getMessage('Yes');
                    } else if (gr.u_personal_information == 'no') {
                        personal_info = gs.getMessage('No');
                    }
                    var attributes = [{
                            key: 'Cote disponibilité',
                            value: gr.getValue('u_availability') || 'N/A'
                        },
                        {
                            key: 'Cote intégrité',
                            value: gr.getValue('u_integrity') || 'N/A'
                        },
                        {
                            key: 'Cote confidentialité',
                            value: gr.getValue('u_confidentiality') || 'N/A'
                        },
                        {
                            key: 'Renseignement personnel',
                            value: personal_info
                        }
                    ];

                    // var tableHeaders = attributes.map(function(attr) {
                    //     return '<th style="border: 1px solid #004b87; padding: 8px; text-align: left;">' + attr.key + '</th>';
                    // }).join('');

                    var tableValues = attributes.map(function(attr) {
                        return '<td style="border: 1px solid #004b87; padding: 8px; text-align: left;">' + attr.key + ' : ' + attr.value + '</td>';
                    }).join('');

                    var table = [
                        '<table style="width: 100%; border-collapse: collapse; font-family: Arial, sans-serif; font-size: 12px;">',
                        '<tbody>',
                        '<tr>',
                        tableValues,
                        '</tr>',
                        '</tbody>',
                        '</table>'
                    ];

                    return table.join('');
                }
                return "<p>(Entity information not found)</p>";
            }


        };

        // Template Builder for creating HTML content
        var TemplateBuilder = {
            buildHTMLContent: function(entity, assessments) {
                var entityInfo = DataAccess.getEntityInformation(entity);
                var assessor = DataAccess.getAssessor(entityId);
                var htmlContent = [
                    '<html><head><style>',

                    // Global font styles
                    'body { font-family: Arial, sans-serif; font-size: 12px; color: #333; margin: 0; padding: 0; }',

                    // First page background styling
                    '.logo { float: left; margin-right: 20px; }',
                    '.header-container { display: flex; flex-direction: column; align-items: flex-start; margin-bottom: 20px; }',
                    '.logo { margin-bottom: 10px; margin-top: -40px; }',

                    // Title style for the first page
                    'h1 { font-size: 24px; color: #004b87; margin: 0;}',
                    'p.subtitle { font-size: 14px; color: #666; text-align: center; margin-top: 10px; margin-bottom: 0; }',

                    // Table styling for subsequent pages
                    'table { width: 100%; border-collapse: collapse; margin-top: 20px; font-family: Arial, sans-serif; }',
                    'th, td { border: 1px solid #004b87; padding: 8px; text-align: left; font-size: 12px; }',
                    'th { background-color: #004b87; color: white; font-weight: bold; font-size: 14px; }',
                    'td { color: #333; }',
                    'tr:nth-child(odd) td { background-color: #f9f9f9; }', // Alternating row colors

                    '</style></head><body>',
                    '<header style="text-align:center; margin-bottom:20px;">',
                    '<div class="logo">',
                    '<img src="data:image/jpeg;base64," alt="Énergir Logo" style="width: 200px; height: auto; display: inline-block;"/>', // Adjust logo size
                    '</div>',
                    '<br>',
                    '</header>',
                    '<div class="title-container">',
                    '<h1>Évaluation de risques</h1>',
                    '</div>', // Translated title to French
                    '<div><h3>Information sur l\'entité</div></h3>',
                    '<p><strong>Nom de l\'entité:</strong> ' + entity.getValue('name') + '</p>',
                    '<p><strong>Propriétaire de l\'actif:</strong> ' + entity.getDisplayValue('u_cmdb_owner') + '</p>',
                    '<p><strong>Description du projet:</strong> ' + entity.getDisplayValue('u_project_description') + '</p>',
                    '<p><strong>Mise en contexte technologique:</strong> ' + entity.getDisplayValue('u_technological_context') + '</p>',
                    '<p><strong>Évalué par:</strong> ' + assessor + '</p>',
                    '<p>' + entityInfo + '</p>',
                    '<div><h3>Détails de l\'évaluation de risques</div></h3>'
                ].join('');

                var index = 1;
                while (assessments.hasNext()) {
                    assessments.next();
                    var controlResponses = DataAccess.getControlResponses(assessments.sys_id);

                    htmlContent += TemplateBuilder.buildRiskSection(assessments, controlResponses, index);
                    index++;
                }

                return htmlContent;
            },



            buildRiskSection: function(assessment, controls) {
                // Score display mappings for Control Effectiveness
                var scoreMapping = {
                    CONTROL: {
                        "1": 'Absence de contrôle',
                        "2": 'Contrôle en place, mais non documenté',
                        "3": 'Contrôle en place, documenté et/ou automatisé'
                    }
                };

                // Helper function to get display text based on score and type
                function getScoreDisplay(score, type) {
                    return scoreMapping[type] && scoreMapping[type][score] ? scoreMapping[type][score] : "Unknown";
                }

                // Start HTML structure for the risk section
                var riskHtml = [
                    '<table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse;">',
                    '<tr>',
                    '<td colspan="2"><strong>Risque:</strong> ' + assessment.risk.name + '</td>',
                    '<td colspan="2"><strong>Description:</strong> ' + assessment.risk.description + '</td>',
                    '</tr>'
                ];

                // Loop through each control and add it to the table
                controls.forEach(function(control, index) {
                    // Alternate background colors for rows
                    var rowStyle = (index % 2 === 0) ? 'background-color: #d0e7ff;' : 'background-color: white;';

                    riskHtml.push(
                        '<tr style="' + rowStyle + '">',
                        '<td style="' + rowStyle + '" colspan="2"><strong>Contrôle:</strong> ' + control.name + '</td>',
                        '<td style="' + rowStyle + '"><strong>Efficacité du contrôle:</strong> ' + getScoreDisplay(control.score, 'CONTROL') + '</td>',
                        '<td style="' + rowStyle + '"><strong>Commentaires:</strong> ' + (control.comments || '') + '</td>',
                        '</tr>'
                    );
                });

                // Close table and div tags
                riskHtml.push('</table></div>');
                return riskHtml.join('');
            },
            // },


            // ... other TemplateBuilder methods
            //  },
            buildAggregatedRiskSection: function(aggregatedRisk) {
                // Start HTML structure for the Aggregated Risk section
                var aggregatedRiskHtml = [
                    '<div><h3>Risques regroupés</h3>',
                    '<table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse;">',
                    '<tr>',
                    '<td><strong>Cote inhérente:</strong> ' + (aggregatedRisk.inherent_rating_display || 'N/A') + '</td>',
                    '<td><strong>Cote résiduelle:</strong> ' + (aggregatedRisk.residual_rating_display || 'N/A') + '</td>',
                    '</tr>',
                    '</table></div>'
                ];
                return aggregatedRiskHtml.join('');
            },
            buildIssuesSection: function(issues) {
                // Start HTML structure for the Issues section
                var issuesHtml = [
                    '<div><h3>Plan d\'action</h3>',
                    '<table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse;">'
                ];

                issues.forEach(function(issue, issueIndex) {
                    // Add Issue row
                    issuesHtml.push(
                        '<tr><td colspan="3"><strong>Plan d\'action ' + (issueIndex + 1) + ':</strong> ' + issue.name + '</td></tr>'
                    );

                    // Get remediation tasks for this issue
                    var remediationTasks = DataAccess.getRemediationTasks(issue.sys_id);

                    remediationTasks.forEach(function(task, taskIndex) {
                        // Add Remediation Task row
                        var rowStyle = (taskIndex % 2 === 0) ? 'background-color: #e5f3ff;' : 'background-color: white;';
                        issuesHtml.push(
                            '<tr style="' + rowStyle + '">',
                            '<td><strong>Tâches de correction ' + (taskIndex + 1) + ':</strong> ' + task.short_description + '</td>',
                            '<td><strong>Description:</strong> ' + task.description + '</td>',
                            '<td><strong>Date de fin planifiée:</strong> ' + (task.planned_end_date || 'N/A') + '</td>',
                            '</tr>'
                        );
                    });
                });

                issuesHtml.push('</table></div>');
                return issuesHtml.join('');
            },
            // Function to build the Approbation section with dynamic assessor
            buildApprobationSection: function(entityId) {
                var assessor = DataAccess.getAssessor(entityId); // Fetch the assessor based on entity ID
                return [
                    '<h3 style="color: #004b87; margin-top: 30px;">Approbation</h3>',
                    '<p>Assessed by: <em>' + assessor + '</em></p>',
                    '<p>Approved by:</p>',
                    '<table>',
                    '<tr><td>Nom:<br>Titre: </td><td>Signature:<br>Date:</td></tr>',
                    '<tr><td></td><td></td></tr>',
                    '<tr><td></td><td></td></tr>',
                    '<tr><td></td><td></td></tr>',
                    '</table>'
                ].join('');
            }
        };

        // Main logic to fetch data and build PDF
        var entity = DataAccess.getEntity(entityId);
        if (!entity) {
            gs.error("Entity not found with ID: " + entityId);
            return null;
        }

        var assessments = DataAccess.getRiskAssessment(entityId);
        var aggregatedRisk = DataAccess.getAggregatedRisk(entityId);
        var issues = DataAccess.getIssues(entityId);
        var htmlContent = TemplateBuilder.buildHTMLContent(entity, assessments);
        htmlContent += TemplateBuilder.buildAggregatedRiskSection(aggregatedRisk);
        htmlContent += TemplateBuilder.buildIssuesSection(issues);
        //  htmlContent += TemplateBuilder.buildApprobationSection(entityId);

        // Generate PDF using sn_pdfgeneratorutils API
        var pdfGenerator = new sn_pdfgeneratorutils.PDFGenerationAPI();
        var pdfDocument = pdfGenerator.convertToPDF(htmlContent, 'sn_grc_profile', entityId, 'RiskAssessmentPDF');

        gs.info("PDF generated successfully with Sys ID: " + pdfDocument);
        return pdfDocument;
    },

    type: 'GenerateRiskAssessmentPDF'
};
